// sqliteQueries answers every query in Querier against sqlite.
type sqliteQueries struct {
	archiveReport                      string
	createReport                       string
	deleteReportsByReporter            string
	getArchivedReport                  string
	getReport                          string
	listReports                        string
	listReportsByReporter              string
	listReportsByReporterDescending    string
	listReportsByStatus                string
	listReportsByStatusDescending      string
	listReportsBySubjectType           string
	listReportsBySubjectTypeDescending string
	listReportsDescending              string
	listReportsForSubject              string
	listReportsForSubjectDescending    string
	transitionReport                   string
	updateReport                       string
}

// newSQLite returns the sqlite querier with prefix substituted into every
// table name the analyzer identified.
func newSQLite(prefix string) *sqliteQueries {
	return &sqliteQueries{
		archiveReport:                      strings.ReplaceAll(archiveReportSQLite, prefixMarker, prefix),
		createReport:                       strings.ReplaceAll(createReportSQLite, prefixMarker, prefix),
		deleteReportsByReporter:            strings.ReplaceAll(deleteReportsByReporterSQLite, prefixMarker, prefix),
		getArchivedReport:                  strings.ReplaceAll(getArchivedReportSQLite, prefixMarker, prefix),
		getReport:                          strings.ReplaceAll(getReportSQLite, prefixMarker, prefix),
		listReports:                        strings.ReplaceAll(listReportsSQLite, prefixMarker, prefix),
		listReportsByReporter:              strings.ReplaceAll(listReportsByReporterSQLite, prefixMarker, prefix),
		listReportsByReporterDescending:    strings.ReplaceAll(listReportsByReporterDescendingSQLite, prefixMarker, prefix),
		listReportsByStatus:                strings.ReplaceAll(listReportsByStatusSQLite, prefixMarker, prefix),
		listReportsByStatusDescending:      strings.ReplaceAll(listReportsByStatusDescendingSQLite, prefixMarker, prefix),
		listReportsBySubjectType:           strings.ReplaceAll(listReportsBySubjectTypeSQLite, prefixMarker, prefix),
		listReportsBySubjectTypeDescending: strings.ReplaceAll(listReportsBySubjectTypeDescendingSQLite, prefixMarker, prefix),
		listReportsDescending:              strings.ReplaceAll(listReportsDescendingSQLite, prefixMarker, prefix),
		listReportsForSubject:              strings.ReplaceAll(listReportsForSubjectSQLite, prefixMarker, prefix),
		listReportsForSubjectDescending:    strings.ReplaceAll(listReportsForSubjectDescendingSQLite, prefixMarker, prefix),
		transitionReport:                   strings.ReplaceAll(transitionReportSQLite, prefixMarker, prefix),
		updateReport:                       strings.ReplaceAll(updateReportSQLite, prefixMarker, prefix),
	}
}

// timeText renders a time argument as the text this engine stores timestamps as.
//
// This engine has no date type: a DATETIME column holds text, and a comparison
// between two of them compares two strings. What a driver writes for a bound
// time.Time is Go's own rendering of it, whose leading characters happen to be
// the stored shape — but only while the value is UTC. A time carrying any other
// zone puts its own wall clock in those leading characters, so every window
// comparison is off by that offset, silently, and only for the callers whose
// clock is not UTC.
//
// Converting here is what makes the bound text the stored shape by
// construction rather than by accident, whatever zone the caller's time
// carries. The layout is whole seconds, which is what CURRENT_TIMESTAMP writes,
// so a bound value and a stored one are one shape rather than two that sort
// alike — which does mean a sub-second time bound here is stored truncated to
// the second on this engine.
func timeText(t time.Time) string {
	return t.UTC().Format("2006-01-02 15:04:05")
}

// timeTextPtr is timeText for a nullable argument. It preserves nil, so a
// field the caller left unset still binds NULL rather than the zero time.
func timeTextPtr(t *time.Time) any {
	if t == nil {
		return nil
	}

	return timeText(*t)
}

// ArchiveReport runs the :execrows query against sqlite.
func (q *sqliteQueries) ArchiveReport(ctx context.Context, db DBTX, arg ArchiveReportParams) (int64, error) {
	result, err := db.ExecContext(ctx, q.archiveReport,
		arg.ID,
		arg.Scope,
	)
	if err != nil {
		return 0, err
	}

	return result.RowsAffected()
}

// CreateReport runs the :exec query against sqlite.
func (q *sqliteQueries) CreateReport(ctx context.Context, db DBTX, arg CreateReportParams) error {
	_, err := db.ExecContext(ctx, q.createReport,
		arg.ID,
		arg.Scope,
		arg.Reporter,
		arg.Kind,
		arg.Details,
		arg.SubjectType,
		arg.SubjectID,
		arg.Status,
		arg.Resolution,
		timeTextPtr(arg.ClosedAt),
	)

	return err
}

// DeleteReportsByReporter runs the :execrows query against sqlite.
func (q *sqliteQueries) DeleteReportsByReporter(ctx context.Context, db DBTX, arg DeleteReportsByReporterParams) (int64, error) {
	result, err := db.ExecContext(ctx, q.deleteReportsByReporter,
		arg.Scope,
		arg.Reporter,
	)
	if err != nil {
		return 0, err
	}

	return result.RowsAffected()
}

// GetArchivedReport runs the :one query against sqlite.
func (q *sqliteQueries) GetArchivedReport(ctx context.Context, db DBTX, arg GetArchivedReportParams) (GetArchivedReportRow, error) {
	row := db.QueryRowContext(ctx, q.getArchivedReport,
		arg.ID,
		arg.Scope,
	)

	var i GetArchivedReportRow

	err := row.Scan(
		&i.ID,
		&i.Scope,
		&i.Reporter,
		&i.Kind,
		&i.Details,
		&i.SubjectType,
		&i.SubjectID,
		&i.Status,
		&i.Resolution,
		&i.ClosedAt,
		&i.CreatedAt,
		&i.LastUpdatedAt,
		&i.ArchivedAt,
	)

	return i, err
}

// GetReport runs the :one query against sqlite.
func (q *sqliteQueries) GetReport(ctx context.Context, db DBTX, arg GetReportParams) (GetReportRow, error) {
	row := db.QueryRowContext(ctx, q.getReport,
		arg.ID,
		arg.Scope,
	)

	var i GetReportRow

	err := row.Scan(
		&i.ID,
		&i.Scope,
		&i.Reporter,
		&i.Kind,
		&i.Details,
		&i.SubjectType,
		&i.SubjectID,
		&i.Status,
		&i.Resolution,
		&i.ClosedAt,
		&i.CreatedAt,
		&i.LastUpdatedAt,
		&i.ArchivedAt,
	)

	return i, err
}

// ListReports runs the :many query against sqlite.
func (q *sqliteQueries) ListReports(ctx context.Context, db DBTX, arg ListReportsParams) ([]ListReportsRow, error) {
	rows, err := db.QueryContext(ctx, q.listReports,
		timeTextPtr(arg.CreatedAfter),
		timeTextPtr(arg.CreatedBefore),
		timeTextPtr(arg.UpdatedAfter),
		timeTextPtr(arg.UpdatedBefore),
		arg.IncludeArchived,
		arg.Scope,
		arg.PageCursor,
		arg.ResultLimit,
	)
	if err != nil {
		return nil, err
	}

	defer func() { _ = rows.Close() }()

	var items []ListReportsRow

	for rows.Next() {
		var i ListReportsRow

		if err := rows.Scan(
			&i.ID,
			&i.Scope,
			&i.Reporter,
			&i.Kind,
			&i.Details,
			&i.SubjectType,
			&i.SubjectID,
			&i.Status,
			&i.Resolution,
			&i.ClosedAt,
			&i.CreatedAt,
			&i.LastUpdatedAt,
			&i.ArchivedAt,
			&i.FilteredCount,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

